def latest_time(s: str) -> str:
    # Convert string to list for easier manipulation
    s_list = list(s)

    # Handle hour part (positions 0 and 1)
    # First hour digit (index 0)
    if s_list[0] == '?':
        # If second hour digit is known and >= '2', first digit must be '0'
        # Otherwise, we can use '1' to get latest time
        if s_list[1] != '?' and s_list[1] >= '2':
            s_list[0] = '0'
        else:
            s_list[0] = '1'

    # Second hour digit (index 1)
    if s_list[1] == '?':
        # If first digit is '0', second can be up to '9'
        # If first digit is '1', second can be up to '1'
        if s_list[0] == '0':
            s_list[1] = '9'
        else:  # s_list[0] == '1'
            s_list[1] = '1'

    # Handle minute part (positions 3 and 4)
    # First minute digit (index 3)
    if s_list[3] == '?':
        s_list[3] = '5'

    # Second minute digit (index 4)
    if s_list[4] == '?':
        s_list[4] = '9'

    return ''.join(s_list)
