def number_of_special_letters(word: str) -> int:
    # Create sets for lowercase and uppercase letters present in the word
    lower_set = set()
    upper_set = set()

    for char in word:
        if char.islower():
            lower_set.add(char)
        else:
            upper_set.add(char.lower())  # Convert to lowercase for comparison

    # Count letters that appear in both sets
    special_count = 0
    for char in lower_set:
        if char in upper_set:
            special_count += 1

    return special_count
```

