def make_smallest_palindrome(s: str) -> str:
    # Convert string to list for easier modification
    chars = list(s)
    left = 0
    right = len(s) - 1

    while left < right:
        if chars[left] != chars[right]:
            # To get lexicographically smallest palindrome, choose the smaller character
            # between the two, since we want to minimize the string lexicographically
            # and we're allowed to change either character
            if chars[left] < chars[right]:
                chars[right] = chars[left]
            else:
                chars[left] = chars[right]
        left += 1
        right -= 1

    return ''.join(chars)
```

