import sys

def read_poly():
    lines = [sys.stdin.readline().strip() for _ in range(4)]
    cells = []
    for i in range(4):
        for j in range(4):
            if lines[i][j] == '#':
                cells.append((i, j))
    return cells

def normalize(cells):
    if not cells:
        return set()
    minr = min(r for r, c in cells)
    minc = min(c for r, c in cells)
    return {(r - minr, c - minc) for r, c in cells}

def rotate_cells(cells, k):
    res = []
    for r, c in cells:
        for _ in range(k):
            r, c = c, -r
        res.append((r, c))
    return normalize(res)

def get_all_shapes(cells):
    shapes = []
    for k in range(4):
        shape = rotate_cells(cells, k)
        if shape not in shapes:
            shapes.append(shape)
    return shapes

def get_placements(shape):
    placements = []
    maxr = max((r for r, c in shape), default=0)
    maxc = max((c for r, c in shape), default=0)
    for dr in range(4 - maxr):
        for dc in range(4 - maxc):
            placed = set()
            valid = True
            for r, c in shape:
                nr, nc = r + dr, c + dc
                if 0 <= nr < 4 and 0 <= nc < 4:
                    placed.add(nr * 4 + nc)
                else:
                    valid = False
                    break
            if valid:
                mask = 0
                for p in placed:
                    mask |= (1 << p)
                placements.append(mask)
    return placements

def can_tile(polys):
    all_placements = []
    for cells in polys:
        shapes = get_all_shapes(cells)
        place_list = []
        for shape in shapes:
            place_list.extend(get_placements(shape))
        all_placements.append(list(set(place_list)))
    for m1 in all_placements[0]:
        for m2 in all_placements[1]:
            if m1 & m2:
                continue
            for m3 in all_placements[2]:
                if m1 & m3 or m2 & m3:
                    continue
                if (m1 | m2 | m3) == (1 << 16) - 1:
                    return True
    return False

polys = [read_poly() for _ in range(3)]
print("Yes" if can_tile(polys) else "No")
```

