def smallestString(s: str) -> str:
    n = len(s)
    s_list = list(s)

    # Find the first non-'a' character
    i = 0
    while i < n and s_list[i] == 'a':
        i += 1

    # If all characters are 'a', convert the last 'a' to 'z'
    if i == n:
        s_list[-1] = 'z'
        return ''.join(s_list)

    # Starting from the first non-'a', convert as many characters as possible
    # until we hit an 'a' again (since converting 'a' to 'z' would make it larger)
    while i < n and s_list[i] != 'a':
        s_list[i] = chr(ord(s_list[i]) - 1)
        i += 1

    return ''.join(s_list)
