def numberOfRightTriangles(grid):
    if not grid or not grid[0]:
        return 0
    m, n = len(grid), len(grid[0])
    row_ones = [0] * m
    col_ones = [0] * n
    for i in range(m):
        for j in range(n):
            if grid[i][j]:
                row_ones[i] += 1
                col_ones[j] += 1
    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j]:
                count += (row_ones[i] - 1) * (col_ones[j] - 1)
    return count
