                if deg[nei] == 2:
                    # find the pair
                    for nn in adj[nei]:
                        if nn != c:
                            pair = nn
                            break
                    if deg[pair] == 2:
                        for other in adj[pair]:
                            if other != nei:
                                if other not in centers:
                                    new_centers.add(other)
                                    changed = True
        centers.update(new_centers)
