import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    H = int(data[0])
    W = int(data[1])
    grid = []
    index = 2
    for i in range(H):
        grid.append(data[index])
        index += 1
    active = [[True for _ in range(W)] for _ in range(H)]
    row_freq = [[0] * 26 for _ in range(H)]
    col_freq = [[0] * 26 for _ in range(W)]
    total_row = [0] * H
    total_col = [0] * W
    for i in range(H):
        for j in range(W):
            c = ord(grid[i][j]) - 97
            row_freq[i][c] += 1
            col_freq[j][c] += 1
            total_row[i] += 1
            total_col[j] += 1
    while True:
        marked_rows = []
        for i in range(H):
            if total_row[i] >= 2:
                colors = 0
                for k in range(26):
                    if row_freq[i][k] > 0:
                        colors += 1
                if colors == 1:
                    marked_rows.append(i)
        marked_cols = []
        for j in range(W):
            if total_col[j] >= 2:
                colors = 0
                for k in range(26):
                    if col_freq[j][k] > 0:
                        colors += 1
                if colors == 1:
                    marked_cols.append(j)
        if not marked_rows and not marked_cols:
            break
        for i in marked_rows:
            for j in range(W):
                if active[i][j]:
                    active[i][j] = False
                    c = ord(grid[i][j]) - 97
                    row_freq[i][c] -= 1  # should become 0
                    col_freq[j][c] -= 1
                    total_col[j] -= 1
            total_row[i] = 0
        for j in marked_cols:
            for i in range(H):
                if active[i][j]:
