    dp = [0] * (1 << 11)
    dp[1] = 1
    for a in A:
        new_dp = [0] * (1 << 11)
        max_add = min(a, 10)
        ways_no_add = max(0, a - 10)
        for mask in range(1 << 11):
            if dp[mask] == 0:
                continue
            if ways_no_add > 0:
                new_dp[mask] = (new_dp[mask] + dp[mask] * ways_no_add) % MOD
            for x in range(1, max_add + 1):
                new_mask = mask
                for s in range(11 - x):
                    if mask & (1 << s):
                        new_mask |= (1 << (s + x))
                new_dp[new_mask] = (new_dp[new_mask] + dp[mask]) % MOD
        dp = new_dp
    fav = 0
    for mask in range(1 << 11):
        if mask & (1 << 10):
            fav = (fav + dp[mask]) % MOD
    ans = fav * modinv(total) % MOD
