import math
from functools import reduce

def kthSmallestAmount(coins, k):
    # Remove duplicates and filter out coins that are multiples of smaller coins
    coins = sorted(set(coins))
    filtered_coins = []
    for coin in coins:
        # Keep only coins that are not multiples of any smaller coin in the list
        is_redundant = False
        for fc in filtered_coins:
            if coin % fc == 0:
                is_redundant = True
                break
        if not is_redundant:
            filtered_coins.append(coin)

    coins = filtered_coins

    # If there's only one coin left, it's the answer: k * coin
    if len(coins) == 1:
        return k * coins[0]

    # For multiple coins, use binary search on the answer
    def count_multiples(x):
        """Count how many multiples of any coin are <= x"""
        # Use inclusion-exclusion principle
        n = len(coins)
        total = 0
        for i in range(1, 1 << n):
            lcm_val = 1
            bits = 0
            for j in range(n):
                if (i >> j) & 1:
                    bits += 1
                    lcm_val = lcm(lcm_val, coins[j])
                    # Early termination if LCM exceeds x
                    if lcm_val > x:
                        break
            else:
                # Only count if LCM didn't exceed x
                if bits % 2 == 1:
                    total += x // lcm_val
                else:
                    total -= x // lcm_val
        return total

    def lcm(a, b):
        return a * b // math.gcd(a, b)

    # Binary search bounds
    lo, hi = 1, k * min(coins)

    # Refine hi using the fact that we need at least k numbers
    # The k-th smallest number is at most k * min(coins)
    while lo < hi:
        mid = (lo + hi) // 2
        cnt = count_multiples(mid)
        if cnt < k:
            lo = mid + 1
        else:
            hi = mid

    return lo
