```python
def stable_binary_arrays(zero: int, one: int, limit: int) -> int:
    MOD = 10**9 + 7

    # dp[i][j][k] = number of stable arrays with i zeros, j ones, ending with k consecutive identical bits (k=1 or 2)
    # But we need to track the last run length to ensure no run exceeds limit
    # We'll use dp[i][j][last][run] where last is 0 or 1, and run is the length of the current run (1 to limit)

    # Let's optimize: dp[i][j][last][run] -> number of ways to form array with i zeros, j ones, ending with 'last' bit, with a run of 'run' consecutive 'last' bits
    # We only need run <= limit

    # Initialize 4D DP array
    dp = [[[[0] * (limit + 1) for _ in range(2)] for _ in range(one + 1)] for _ in range(zero + 1)]

    # Base cases: single element arrays
    if zero >= 1:
        dp[1][0][0][1] = 1
    if one >= 1:
        dp[0][1][1][1] = 1

    # Fill the DP table
    for i in range(zero + 1):
        for j in range(one + 1):
            for last in range(2):
                for run in range(1, limit + 1):
                    if dp[i][j][last][run] == 0:
                        continue

                    # Try to append a 0
                    if i + 1 <= zero:
                        if last == 0:  # appending to a run of 0s
                            if run + 1 <= limit:
                                dp[i + 1][j][0][run + 1] = (dp[i + 1][j][0][run + 1] + dp[i][j][last][run]) % MOD
                        else:  # last == 1, start new run of 0s
                            dp[i + 1][j][0][1] = (dp[i + 1][j][0][1] + dp[i][j][last][run]) % MOD

                    # Try to append a 1
                    if j + 1 <= one:
                        if last == 1:  # appending to a run of 1s
                            if run + 1 <= limit:
                                dp[i][j + 1][1][run + 1] = (dp[i][j + 1][1][run + 1] + dp[i][j][last][run]) % MOD
                        else:  # last == 0, start new run of 1s
                            dp[i][j + 1][1][1] = (dp[i][j + 1][1][1] + dp[i][j][last][run]) % MOD

    # Sum all dp[zero][one][last][run] for last in {0,1} and run in [1, limit]
    result = 0
    for last in range(2):
        for run in range(1, limit + 1):
            result = (result + dp[zero][one][last][run]) % MOD

    return result
