def minimum_sum(n: int, k: int) -> int:
    # We want to construct the lexicographically smallest k-avoiding array of length n
    # to minimize the sum. The idea is to greedily select the smallest possible integers
    # while ensuring no two elements sum to k.

    selected = []
    current = 1

    while len(selected) < n:
        # Check if adding 'current' would create a pair that sums to k
        valid = True
        for num in selected:
            if num + current == k:
                valid = False
                break

        if valid:
            selected.append(current)

        current += 1

    return sum(selected)
