def punishment_number(n):
    def can_partition(num_str, target):
        # Try all possible partitions using backtracking
        def backtrack(index, current_sum, parts):
            if index == len(num_str):
                return current_sum == target

            for end in range(index + 1, len(num_str) + 1):
                part = int(num_str[index:end])
                # Early termination if current sum exceeds target
                if current_sum + part > target:
                    break
                if backtrack(end, current_sum + part, parts + 1):
                    return True
            return False

        return backtrack(0, 0, 0)

    total = 0
    for i in range(1, n + 1):
        square = i * i
        square_str = str(square)
        if can_partition(square_str, i):
            total += square
    return total
