def can_tile(H, W, rects):
    K = len(rects)
    if K == 0:
        return H == 0 and W == 0
    grid = [[False for _ in range(W)] for _ in range(H)]

    def find_next_empty():
        for i in range(H):
            for j in range(W):
                if not grid[i][j]:
                    return i, j
        return None

    def can_place(r, c, h, w):
        if r + h > H or c + w > W:
            return False
        for i in range(h):
            for j in range(w):
                if grid[r + i][c + j]:
                    return False
        return True

