        if pos is None:
            return True
        r, c = pos
        for idx in range(K):
            if used[idx]:
                continue
            h, w = rects[idx]
            # try this orientation
            if can_place(r, c, h, w):
                do_place(r, c, h, w, True)
                used[idx] = True
                if bt(used_count + 1):
                    return True
                used[idx] = False
                do_place(r, c, h, w, False)
            # try rotated if different
            if h != w:
                hr, wr = w, h
                if can_place(r, c, hr, wr):
