```python
def canSortArray(nums):
    # Helper function to count set bits
    def count_set_bits(n):
        return bin(n).count('1')

    # Create groups of numbers with the same number of set bits
    # Within each group, we can rearrange elements arbitrarily (since adjacent swaps are allowed)
    # So we can sort each group individually

    # We'll create a list of (value, set_bits) pairs
    elements = [(num, count_set_bits(num)) for num in nums]

    # Group elements by their set bit count, preserving original order within group
    groups = {}
    for i, (val, bits) in enumerate(elements):
        if bits not in groups:
            groups[bits] = []
        groups[bits].append(val)

    # Sort each group individually
    for bits in groups:
        groups[bits].sort()

    # Reconstruct the array by taking the next element from each group in order
    # But we need to maintain the original grouping structure: for each position,
    # we take from the group corresponding to the original element's bit count
    result = []
    # Use pointers for each group
    pointers = {bits: 0 for bits in groups}

    # Rebuild the array: for each original position i, take the next smallest element from the group of nums[i]
    for val, bits in elements:
        result.append(groups[bits][pointers[bits]])
        pointers[bits] += 1

    # Check if the result array is sorted
    return result == sorted(nums)
