def findOccurrences(nums, queries, x):
    # First, collect all indices where x appears in nums
    indices = []
    for i, num in enumerate(nums):
        if num == x:
            indices.append(i)

    # For each query, get the (query-1)th index if it exists
    answer = []
    for query in queries:
        # query is 1-indexed, so we need index at position query-1
        if query <= len(indices):
            answer.append(indices[query - 1])
        else:
            answer.append(-1)

    return answer
