def beautifulIndices(s: str, a: str, b: str, k: int) -> list[int]:
    # Find all indices where string a appears in s
    a_indices = []
    for i in range(len(s) - len(a) + 1):
        if s[i:i + len(a)] == a:
            a_indices.append(i)

    # Find all indices where string b appears in s
    b_indices = []
    for j in range(len(s) - len(b) + 1):
        if s[j:j + len(b)] == b:
            b_indices.append(j)

    # For each index where a appears, check if there's a b within distance k
    result = []
    for i in a_indices:
        # Check if there exists a j in b_indices such that |j - i| <= k
        # Using binary search for efficiency since b_indices is sorted
        left, right = 0, len(b_indices) - 1
        found = False
        while left <= right:
            mid = (left + right) // 2
            if abs(b_indices[mid] - i) <= k:
                found = True
                break
            elif b_indices[mid] < i - k:
                left = mid + 1
            else:  # b_indices[mid] > i + k
                right = mid - 1

        if found:
            result.append(i)

    return result
