from math import gcd
from collections import defaultdict, deque

def can_traverse_all_pairs(nums):
    n = len(nums)
    if n == 1:
        return True

    # Build a graph where nodes are indices and edges exist between indices i, j if gcd(nums[i], nums[j]) > 1
    # However, building all edges explicitly would be O(n^2), which is too slow for n up to 10^5
    # Instead, use union-find with prime factorization

    # Union-Find data structure
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return
        if rank[px] < rank[py]:
            parent[px] = py
        elif rank[px] > rank[py]:
            parent[py] = px
        else:
            parent[py] = px
            rank[px] += 1

    # Map each prime factor to a list of indices that have this factor
    prime_to_indices = defaultdict(list)

    # For each number, find its prime factors
    for i, num in enumerate(nums):
        # Handle prime factorization
        temp = num
        d = 2
        while d * d <= temp:
            if temp % d == 0:
                prime_to_indices[d].append(i)
                while temp % d == 0:
                    temp //= d
            d += 1
        if temp > 1:  # temp is prime
            prime_to_indices[temp].append(i)

    # For each prime factor, union all indices that have this factor
    for prime, indices in prime_to_indices.items():
        for i in range(1, len(indices)):
            union(indices[0], indices[i])

    # Check if all indices are in the same connected component
    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False

    return True
