def maximumPrimeDistance(nums):
    # Helper function to check if a number is prime
    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        # Check odd divisors up to sqrt(n)
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    # Find all indices where the element is prime
    prime_indices = []
    for i, num in enumerate(nums):
        if is_prime(num):
            prime_indices.append(i)

    # The maximum distance is between the first and last prime indices
    return prime_indices[-1] - prime_indices[0]
