def specialPermutations(nums):
    MOD = 10**9 + 7
    n = len(nums)

    # Precompute which pairs (i, j) satisfy nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
    valid = [[False] * n for _ in range(n)]
    for i in range(n):
        for j in range(n):
            if i == j:
                valid[i][j] = True  # Same element trivially satisfies the condition
            else:
                valid[i][j] = (nums[i] % nums[j] == 0) or (nums[j] % nums[i] == 0)

    # dp[mask][last] = number of ways to form a permutation using elements in mask (bitmask)
    # where the last element is at index 'last'
    dp = {}

    # Initialize: permutations of length 1
    for i in range(n):
        mask = 1 << i
        dp[(mask, i)] = 1

    # Iterate through all masks from smallest to largest
    for mask in range(1, 1 << n):
        # Skip masks with only one bit set (already initialized)
        if bin(mask).count('1') == 1:
            continue

        # For each possible last element in current permutation
        for last in range(n):
            # Check if last element is in the mask
            if not (mask & (1 << last)):
                continue

            # Remove the last element to get previous mask
            prev_mask = mask ^ (1 << last)

            # For each possible previous element
            for prev in range(n):
                # Check if prev element is in the previous mask
                if not (prev_mask & (1 << prev)):
                    continue

                # Check if we can transition from prev to last
                if valid[prev][last]:
                    dp[(mask, last)] = dp.get((mask, last), 0) + dp.get((prev_mask, prev), 0)
                    dp[(mask, last)] %= MOD

    # Sum over all permutations that use all elements (mask = (1 << n) - 1)
    full_mask = (1 << n) - 1
    result = 0
    for last in range(n):
        result = (result + dp.get((full_mask, last), 0)) % MOD

    return result
```

