def maximumSumQueries(nums1, nums2, queries):
    n = len(nums1)
    pairs = sorted(zip(nums1, nums2), key=lambda x: -x[0])
    q = [(i, x, y) for i, (x, y) in enumerate(queries)]
    q.sort(key=lambda x: -x[1])
    vals = sorted(set(nums2))
    m = len(vals)
    rank = {v: i for i, v in enumerate(vals)}
    tree = [-1] * (4 * m)

    def update(idx, val, node=1, l=0, r=m-1):
        if l == r:
            tree[node] = max(tree[node], val)
            return
        mid = (l + r) // 2
        if idx <= mid:
            update(idx, val, node * 2, l, mid)
        else:
            update(idx, val, node * 2 + 1, mid + 1, r)
        tree[node] = max(tree[node * 2], tree[node * 2 + 1])

    def query(L, node=1, l=0, r=m-1):
        if L > r:
            return -1
        if L <= l:
            return tree[node]
        mid = (l + r) // 2
        return max(query(L, node * 2, l, mid), query(L, node * 2 + 1, mid + 1, r))

    ans = [0] * len(queries)
    j = 0
    for qi, x, y in q:
        while j < n and pairs[j][0] >= x:
            a, b = pairs[j]
            update(rank[b], a + b)
            j += 1
        r = bisect.bisect_left(vals, y)
        ans[qi] = query(r) if r < m else -1
    return ans
```

