def maximumSumOfSquares(nums, k):
    MOD = 10**9 + 7
    cnt = [0] * 32
    for num in nums:
        for b in range(32):
            if num & (1 << b):
                cnt[b] += 1
    ms = [min(c, k) for c in cnt]
    vals = [0] * k
    for b in range(32):
        m = ms[b]
        if m > 0:
            val_add = 1 << b
            for j in range(m):
                vals[j] += val_add
    ans = 0
    for v in vals:
        ans = (ans + (v * v) % MOD) % MOD
    return ans
