def min_operations(s1: str, s2: str, s3: str) -> int:
    # Find the length of the longest common prefix
    L = 0
    min_len = min(len(s1), len(s2), len(s3))
    while L < min_len and s1[L] == s2[L] == s3[L]:
        L += 1
    # If no common character at the first position, impossible
    if L == 0:
        return -1
    # Total deletions = sum of (original length - common prefix length)
    return (len(s1) - L) + (len(s2) - L) + (len(s3) - L)
```

