def findMinimumOperations(s1: str, s2: str, s3: str) -> int:
    # To make strings equal by deleting from the right, they must share a common prefix.
    # If the first characters are not the same, they can never be made equal.
    if s1[0] != s2[0] or s1[0] != s3[0] or s2[0] != s3[0]:
        return -1

    # Find the length of the longest common prefix among the three strings
    min_len = min(len(s1), len(s2), len(s3))
    common_prefix_len = 0

    for i in range(min_len):
        if s1[i] == s2[i] == s3[i]:
            common_prefix_len += 1
        else:
            break

    # The total operations needed is the sum of characters to delete from each string
    # to reduce them all to the length of the longest common prefix.
    total_len = len(s1) + len(s2) + len(s3)
    return total_len - (3 * common_prefix_len)
```

