import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    N = int(next(it))
    M = int(next(it))
    L = [int(next(it)) for _ in range(N)]

    # Helper function: check if width W can arrange words in <= M lines
    def feasible(W: int) -> bool:
        lines = 1
        current_width = 0  # width of current line without trailing space
        first_word_on_line = True
        for w in L:
            if first_word_on_line:
                # No leading space for the first word on the line
                if w > W:
                    return False  # word itself cannot fit (should not happen as W >= max(L))
                current_width = w
                first_word_on_line = False
            else:
                # Need 1 space before this word
                if current_width + 1 + w > W:
                    # Start new line
                    lines += 1
                    if lines > M:
                        return False
                    current_width = w
                    first_word_on_line = False
                else:
                    current_width += 1 + w
        return lines <= M

    # Binary search boundaries
    lo = max(L) - 1  # definitely impossible when width < max(L)
    hi = sum(L) + N  # definitely possible (one line with all words + spaces)
    while lo + 1 < hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            hi = mid
        else:
            lo = mid
    print(hi)

if __name__ == "__main__":
    solve()
