from typing import List
from collections import defaultdict

def canTraverseAllPairs(nums: List[int]) -> bool:
    n = len(nums)
    if n == 1:
        return True

    max_num = max(nums)

    # Sieve for smallest prime factor
    spf = list(range(max_num + 1))
    for i in range(2, int(max_num**0.5) + 1):
        if spf[i] == i:
            for j in range(i * i, max_num + 1, i):
                if spf[j] == j:
                    spf[j] = i

    def get_prime_factors(x: int):
        if x == 1:
            return set()
        factors = set()
        while x > 1:
            p = spf[x]
            factors.add(p)
            while x % p == 0:
                x //= p
        return factors

    prime_to_indices = defaultdict(list)
    for i, num in enumerate(nums):
        for p in get_prime_factors(num):
            prime_to_indices[p].append(i)

    # Union-Find
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        if parent[x] != x:
            parent[x] = find(parent[x])
        return parent[x]

    def union(x, y):
        px, py = find(x), find(y)
        if px == py:
            return
        if rank[px] < rank[py]:
            parent[px] = py
        elif rank[px] > rank[py]:
            parent[py] = px
        else:
            parent[py] = px
            rank[px] += 1

    for indices in prime_to_indices.values():
        if len(indices) > 1:
            first = indices[0]
            for idx in indices[1:]:
                union(first, idx)

    root = find(0)
    for i in range(1, n):
        if find(i) != root:
            return False
    return True
