def sumOfPowers(nums, k):
    MOD = 10**9 + 7
    nums.sort()
    n = len(nums)
    if n == 0 or k == 0:
        return 0

    max_diff = nums[-1] - nums[0]

    # collect all possible differences between two elements
    diffs = set()
    for i in range(n):
        for j in range(i + 1, n):
            diffs.add(nums[j] - nums[i])

    # critical points where count_ge(d) changes
    breakpoints = {1}
    for d in diffs:
        breakpoints.add(d + 1)
    breakpoints.add(max_diff + 1)
    breakpoints = sorted(breakpoints)

    # count subsequences of length k with minimum difference >= d
    def count_ge(d):
        # dp[i][j] = ways ending at index i
        dp = [[0] * (k + 1) for _ in range(n)]
        for i in range(n):
            dp[i][1] = 1

        for j in range(2, k + 1):
            # prefix sum of dp[*][j-
            pref = [0] * n
            acc = 0
            for i in range(n):
                acc = (acc + dp[i][j - 1]) % MOD
                pref[i] = acc

            left = -1
            for i in range(n):
                # move left pointer
                while left + 1 < i and nums[i] - nums[left + 1] >= d:
                    left += 1
                if left >= 0:
                    dp[i][j] = pref[left]
                else:
                    dp[i][j] = 0

        total = sum(dp[i][k] for i in range(n)) % MOD
        return total

    ans = 0
    for idx in range(len(breakpoints) - 1):
        b = breakpoints[idx]
        nxt = breakpoints[idx + 1]
        end = min(nxt - 1, max_diff)
        if b <= end:
            cnt = count_ge(b)
            ans = (ans + cnt * (end - b + 1)) % MOD

    return ans
```

