from typing import List

def sumOfPowers(nums: List[int], k: int) -> int:
    MOD = 10**9 + 7
    nums.sort()
    n = len(nums)
    diffs = set([0])
    for i in range(n):
        for j in range(i + 1, n):
            diffs.add(nums[j] - nums[i])
    D = sorted(list(diffs))

    def count_ways(delta):
        if k == 0:
            return 1
        dp = [[0] * (k + 1) for _ in range(n)]
        for i in range(n):
            dp[i][1] = 1
        for j in range(2, k + 1):
            prefix = [0] * (n + 1)
            for ii in range(n):
                prefix[ii + 1] = (prefix[ii] + dp[ii][j - 1]) % MOD
            ptr = 0
            for i in range(n):
                while ptr < i and nums[ptr] <= nums[i] - delta:
                    ptr += 1
                dp[i][j] = prefix[ptr]
        total = 0
        for i in range(n):
            total = (total + dp[i][k]) % MOD
        return total

    ans = 0
    for ii in range(len(D) - 1):
        s = D[ii]
        delta = s + 1
        g = count_ways(delta)
        num_t = D[ii + 1] - D[ii]
        contrib = ((num_t % MOD) * g) % MOD
        ans = (ans + contrib) % MOD
    return ans
