    total = n * (n + 1) // 2
    k = (total - 1) // 2 + 1

    def count_at_most(x: int) -> int:
        left = 0
        freq = {}
        distinct = 0
        cnt = 0
        for right in range(n):
            if nums[right] not in freq:
                freq[nums[right]] = 0
            freq[nums[right]] += 1
            if freq[nums[right]] == 1:
                distinct += 1
            while distinct > x and left <= right:
                freq[nums[left]] -= 1
                if freq[nums[left]] == 0:
